// JSON-pointer $ref resolution (local refs only).

// Unescape a single JSON-pointer segment: ~1 -> /, then ~0 -> ~.
export function unescapeSegment(segment) {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

// Resolve a local reference like "#", "#/definitions/name" or "#/$defs/x"
// against the root schema. Throws on anything unresolvable (mirrors the
// reference executable crashing with exit code 1).
export function resolveLocalRef(root, ref) {
  if (typeof ref !== 'string') {
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  if (!ref.startsWith('#')) {
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  let fragment = ref.slice(1);
  if (fragment === '') return root;
  try {
    fragment = decodeURIComponent(fragment);
  } catch {
    // keep the raw fragment
  }
  if (!fragment.startsWith('/')) {
    // plain-name fragments / anchors are unsupported
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  const segments = fragment.slice(1).split('/').map(unescapeSegment);
  let current = root;
  for (const seg of segments) {
    if (Array.isArray(current)) {
      if (!/^\d+$/.test(seg)) throw new Error(`Unresolvable reference: ${ref}`);
      const idx = Number(seg);
      if (idx >= current.length) throw new Error(`Unresolvable reference: ${ref}`);
      current = current[idx];
    } else if (typeof current === 'object' && current !== null) {
      if (!(seg in current)) throw new Error(`Unresolvable reference: ${ref}`);
      current = current[seg];
    } else {
      throw new Error(`Unresolvable reference: ${ref}`);
    }
  }
  return current;
}

