// Validator core: iterErrors/isValid, keyword dispatch, $ref resolution and
// evaluated-properties/items annotation tracking for unevaluated* keywords.

import { isObject } from './jsonvalues.mjs';
import { resolveLocalRef } from './pointer.mjs';

// Marker object for a single yielded validation error (only counts matter).
const ERROR = Object.freeze({});

export class Validator {
  // config: { keywords: Map<string, handler>, refExclusive: boolean }
  constructor(rootSchema, config) {
    this.root = rootSchema;
    this.config = config;
  }

  isValid(instance, schema = this.root) {
    for (const _ of this.iterErrors(instance, schema)) return false;
    return true;
  }

  countErrors(instance, schema = this.root) {
    let n = 0;
    for (const _ of this.iterErrors(instance, schema)) n++;
    return n;
  }

  *iterErrors(instance, schema) {
    if (schema === true) return;
    if (schema === false) {
      yield ERROR;
      return;
    }
    if (!isObject(schema)) {
      // Python crashes (AttributeError) on non-object schemas
      throw new Error('Schema is not an object');
    }
    // Drafts <= 7 ignore sibling keywords when $ref is present.
    if (this.config.refExclusive && schema.$ref !== undefined) {
      const handler = this.config.keywords.get('$ref');
      yield* handler(this, schema.$ref, instance, schema);
      return;
    }
    for (const [key, handler] of this.config.keywords) {
      if (key in schema) {
        yield* handler(this, schema[key], instance, schema);
      }
    }
  }

  resolveRef(ref) {
    return resolveLocalRef(this.root, ref);
  }

  // --- evaluated annotation tracking (2019-09 / 2020-12) ---

  findEvaluatedProps(instance, schema) {
    const evaluated = new Set();
    const walk = (sch) => {
      if (!isObject(sch)) return;
      if (typeof sch.$ref === 'string') walk(this.resolveRef(sch.$ref));
      if (isObject(sch.properties)) {
        for (const k of Object.keys(sch.properties)) {
          if (k in instance) evaluated.add(k);
        }
      }
      if (isObject(sch.patternProperties)) {
        for (const pat of Object.keys(sch.patternProperties)) {
          const re = new RegExp(pat, 'u');
          for (const k of Object.keys(instance)) {
            if (re.test(k)) evaluated.add(k);
          }
        }
      }
      if ('additionalProperties' in sch) {
        const props = isObject(sch.properties) ? Object.keys(sch.properties) : [];
        const patterns = isObject(sch.patternProperties)
          ? Object.keys(sch.patternProperties).map((p) => new RegExp(p, 'u'))
          : [];
        for (const k of Object.keys(instance)) {
          if (props.includes(k)) continue;
          if (patterns.some((re) => re.test(k))) continue;
          evaluated.add(k);
        }
      }
      for (const kw of ['allOf', 'anyOf', 'oneOf']) {
        if (Array.isArray(sch[kw])) {
          for (const sub of sch[kw]) {
            if (this.isValid(instance, sub)) walk(sub);
          }
        }
      }
      if ('if' in sch) {
        if (this.isValid(instance, sch.if)) {
          walk(sch.if);
          if ('then' in sch) walk(sch.then);
        } else if ('else' in sch) {
          walk(sch.else);
        }
      }
    };
    walk(schema);
    return evaluated;
  }

  findEvaluatedIndexes(instance, schema) {
    const evaluated = new Set();
    const addRange = (from, to) => {
      for (let i = from; i < to; i++) evaluated.add(i);
    };
    const walk = (sch) => {
      if (!isObject(sch)) return;
      if (typeof sch.$ref === 'string') walk(this.resolveRef(sch.$ref));
      if ('items' in sch) {
        if (isObject(sch.items) || typeof sch.items === 'boolean') {
          // schema form: every index is evaluated
          addRange(0, instance.length);
        } else if (Array.isArray(sch.items)) {
          addRange(0, Math.min(sch.items.length, instance.length));
          if (isObject(sch.additionalItems) || typeof sch.additionalItems === 'boolean') {
            addRange(sch.items.length, instance.length);
          }
        }
      }
      if (Array.isArray(sch.prefixItems)) {
        addRange(0, Math.min(sch.prefixItems.length, instance.length));
        if ('items' in sch) addRange(sch.prefixItems.length, instance.length);
      }
      if ('contains' in sch) {
        for (let i = 0; i < instance.length; i++) {
          if (this.isValid(instance[i], sch.contains)) evaluated.add(i);
        }
      }
      for (const kw of ['allOf', 'anyOf', 'oneOf']) {
        if (Array.isArray(sch[kw])) {
          for (const sub of sch[kw]) {
            if (this.isValid(instance, sub)) walk(sub);
          }
        }
      }
      if ('if' in sch) {
        if (this.isValid(instance, sch.if)) {
          walk(sch.if);
          if ('then' in sch) walk(sch.then);
        } else if ('else' in sch) {
          walk(sch.else);
        }
      }
    };
    walk(schema);
    return evaluated;
  }
}

export { ERROR };

