  if (isObject(aI) || typeof aI === 'boolean') {
    if (aI === false) {
      if (instance.length > lenItems) yield ERROR;
    } else {
      for (let i = lenItems; i < instance.length; i++) {
        yield* v.iterErrors(instance[i], aI);
      }
    }
  } else if (!aI) {
    if (instance.length > lenItems) yield ERROR;
  }
