// argparse-style manual CLI parsing for --a/--b.

import { basename } from 'node:path';

// argparse's negative-number matcher; tokens like -5 or -1.5 are values,
// not options (the parser has no number-like option strings).
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test13.mjs');
  const usage = `usage: ${prog} [-h] --a A --b B`;
  const helpText = [
    usage,
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A       instance (JSON string)',
    '  --b B       schema (JSON string)',
  ].join('\n');

  const fail = (message) => {
    console.error(usage);
    console.error(`${prog}: error: ${message}`);
    process.exit(2);
  };

  const values = {};
  const extras = [];
  const args = argv.slice(2);

  for (let i = 0; i < args.length; i++) {
    const token = args[i];
    if (token === '-h' || token === '--help') {
      console.log(helpText);
      process.exit(0);
    }
    let name = token;
    let value;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      value = token.slice(eq + 1);
    }
    if (name === '--a' || name === '--b') {
      if (value === undefined) {
        const next = args[i + 1];
        if (next === undefined || isOptionLike(next)) {
          fail(`argument ${name}: expected one argument`);
        }
        value = next;
        i++;
      }
      values[name] = value;
    } else {
      extras.push(token);
    }
  }

  const missing = [];
  if (!('--a' in values)) missing.push('--a');
  if (!('--b' in values)) missing.push('--b');
  if (missing.length) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values['--a'], b: values['--b'] };
}

