args.content:
// Python-flavored JSON parsing.
//
// Python's json.loads distinguishes int from float (1 vs 1.0), and the
// jsonschema draft-03/04 type checkers reject non-int numbers for
// "integer". JS collapses both to `number`, so floats are boxed in a
// PyFloat wrapper to preserve the distinction. Python's json also accepts
// NaN/Infinity/-Infinity.

export class PyFloat {
  constructor(value) {
    this.value = value;
  }
}

export const isPyFloat = (x) => x instanceof PyFloat;

export const isNumeric = (x) => typeof x === 'number' || x instanceof PyFloat;

export const numVal = (x) => (x instanceof PyFloat ? x.value : x);

export function parsePythonJson(text) {
  let i = 0;
  const n = text.length;

  const error = (msg) => {
    throw new Error(`JSONDecodeError: ${msg}`);
  };

  const skipWs = () => {
    while (i < n && (text[i] === ' ' || text[i] === '\t' || text[i] === '\n' || text[i] === '\r')) i++;
  };

  const parseString = () => {
    // assumes text[i] === '"'
    i++;
    let out = '';
    while (i < n) {
      const c = text[i];
      if (c === '"') {
        i++;
        return out;
      }
      if (c === '\\') {
        i++;
        if (i >= n) break;
        const e = text[i];
        switch (e) {
          case '"': out += '"'; i++; break;
          case '\\': out += '\\'; i++; break;
          case '/': out += '/'; i++; break;
          case 'b': out += '\b'; i++; break;
          case 'f': out += '\f'; i++; break;
          case 'n': out += '\n'; i++; break;
          case 'r': out += '\r'; i++; break;
          case 't': out += '\t'; i++; break;
          case 'u': {
            const hex = text.slice(i + 1, i + 5);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) error('Invalid \\uXXXX escape');
            const code = parseInt(hex, 16);
            out += String.fromCharCode(code);
            i += 5;
            break;
          }
          default:
            error(`Invalid \\escape: ${e}`);
        }
      } else if (c < ' ') {
        error('Invalid control character');
      } else {
        out += c;
        i++;
      }
    }
    error('Unterminated string');
  };

  const parseNumber = () => {
    const start = i;
    if (text[i] === '-') i++;
    if (text.startsWith('Infinity', i)) {
      i += 8;
      return new PyFloat(text[start] === '-' ? -Infinity : Infinity);
    }
    if (i >= n || !/[0-9]/.test(text[i])) error('Expecting value');
    if (text[i] === '0') {
      i++;
    } else {
      while (i < n && /[0-9]/.test(text[i])) i++;
    }
    let isFloat = false;
    if (text[i] === '.') {
      isFloat = true;
      i++;
      if (i >= n || !/[0-9]/.test(text[i])) error('Expecting value');
      while (i < n && /[0-9]/.test(text[i])) i++;
    }
    if (text[i] === 'e' || text[i] === 'E') {
      isFloat = true;
      i++;
      if (text[i] === '+' || text[i] === '-') i++;
      if (i >= n || !/[0-9]/.test(text[i])) error('Expecting value');
      while (i < n && /[0-9]/.test(text[i])) i++;
    }
    const raw = text.slice(start, i);
    const value = Number(raw);
    return isFloat ? new PyFloat(value) : value;
  };

  const parseValue = () => {
    skipWs();
    if (i >= n) error('Expecting value');
    const c = text[i];
    if (c === '{') {
      i++;
      const obj = {};
      skipWs();
      if (text[i] === '}') {
        i++;
        return obj;
      }
      while (true) {
        skipWs();
        if (text[i] !== '"') error('Expecting property name');
        const key = parseString();
        skipWs();
        if (text[i] !== ':') error("Expecting ':' delimiter");
        i++;
        obj[key] = parseValue();
        skipWs();
        if (text[i] === ',') {
          i++;
          continue;
        }
        if (text[i] === '}') {
          i++;
          return obj;
        }
        error("Expecting ',' delimiter");
      }
    }
    if (c === '[') {
      i++;
      const arr = [];
      skipWs();
      if (text[i] === ']') {
        i++;
        return arr;
      }
      while (true) {
        arr.push(parseValue());
        skipWs();
        if (text[i] === ',') {
          i++;
          continue;
        }
        if (text[i] === ']') {
          i++;
          return arr;
        }
        error("Expecting ',' delimiter");
      }
    }
    if (c === '"') return parseString();
    if (c === 't' && text.startsWith('true', i)) {
      i += 4;
      return true;
    }
    if (c === 'f' && text.startsWith('false', i)) {
      i += 5;
      return false;
    }
    if (c === 'n' && text.startsWith('null', i)) {
      i += 4;
      return null;
    }
    if (c === 'N' && text.startsWith('NaN', i)) {
      i += 3;
      return new PyFloat(NaN);
    }
    if (c === 'I' && text.startsWith('Infinity', i)) {
      i += 8;
      return new PyFloat(Infinity);
    }
    return parseNumber();
  };

  const result = parseValue();
  skipWs();
  if (i !== n) error('Extra data');
  return result;
}

