// Python-flavored JSON value utilities: type checks and deep equality
// matching the semantics of the Python `jsonschema` library.

import { PyFloat, isNumeric, numVal } from './pyjson.mjs';

export function isObject(x) {
  return typeof x === 'object' && x !== null && !Array.isArray(x) && !(x instanceof PyFloat);
}

export function isArray(x) {
  return Array.isArray(x);
}

// String length in Unicode code points (Python's len()).
export function codePointLength(s) {
  return [...s].length;
}

// Python jsonschema type checking. Options:
//   allowAny       - draft-03 "any" type
//   strictInteger  - draft-03/04: "integer" means Python int (floats like
//                    1.0 are rejected); later drafts accept integral floats.
// Unknown type names throw (mirrors jsonschema's UnknownType -> crash, exit 1).
export function checkType(instance, type, { allowAny = false, strictInteger = false } = {}) {
  switch (type) {
    case 'null':
      return instance === null;
    case 'boolean':
      return instance === true || instance === false;
    case 'object':
      return isObject(instance);
    case 'array':
      return Array.isArray(instance);
    case 'number':
      return isNumeric(instance);
    case 'integer':
      if (strictInteger) {
        return typeof instance === 'number' && Number.isInteger(instance);
      }
      return isNumeric(instance) && Number.isInteger(numVal(instance));
    case 'string':
      return typeof instance === 'string';
    case 'any':
      if (allowAny) return true;
      throw new Error(`Unknown type: ${type}`);
    default:
      throw new Error(`Unknown type: ${type}`);
  }
}

// Deep equality matching observed jsonschema behavior: booleans are always
// distinct from numbers (recursively), numeric values compare by value
// (1 == 1.0, including boxed floats), objects ignore key order.
export function deepEqual(a, b) {
  if (isNumeric(a) && isNumeric(b)) return numVal(a) === numVal(b);
  if (isNumeric(a) !== isNumeric(b)) {
    // numbers are never equal to booleans/strings/null/objects
    return false;
  }
  const ta = typeof a;
  const tb = typeof b;
  if (ta !== tb) return false;
  if (ta !== 'object') return a === b; // string, boolean
  if (a === null || b === null) return a === b;
  const aArr = Array.isArray(a);
  const bArr = Array.isArray(b);
  if (aArr !== bArr) return false;
  if (aArr) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!(k in b) || !deepEqual(a[k], b[k])) return false;
  }
  return true;
}

