import {
  isObject,
  checkType,
  deepEqual,
  codePointLength,
} from './jsonvalues.mjs';
import { PyFloat, isNumeric, numVal } from './pyjson.mjs';
import { ERROR } from './engine.mjs';

const ensureList = (x) => (Array.isArray(x) ? x : [x]);

// Python comparisons treat bools as 1/0 and crash (TypeError) on
// non-numeric keyword values.
const numericLimit = (x) => {
  const v = x === true ? 1 : x === false ? 0 : numVal(x);
  if (typeof v !== 'number') throw new Error('TypeError: not comparable');
  return v;
};

// --- generic ---

export function* typeNormal(v, types, instance) {
  for (const t of ensureList(types)) {
    if (checkType(instance, t)) return;
  }
  yield ERROR;
}

// Draft 4: "integer" means Python int (floats rejected).
export function* typeLegacy(v, types, instance) {
  for (const t of ensureList(types)) {
    if (checkType(instance, t, { strictInteger: true })) return;
  }
  yield ERROR;
}

