export function* multipleOf(v, dB, instance) {
  if (!isNumeric(instance)) return;
  const inst = numVal(instance);
  const db = dB === true ? 1 : dB === false ? 0 : numVal(dB);
  if (typeof db !== 'number') throw new Error('TypeError: not comparable');
  if (db === 0) throw new Error('ZeroDivisionError');
  let failed;
  if (dB instanceof PyFloat) {
    // Python: isinstance(dB, float) -> quotient = instance / dB
    const quotient = inst / db;
    if (Number.isNaN(quotient)) throw new Error('ValueError');
    failed = !Number.isFinite(quotient) || Math.trunc(quotient) !== quotient;
  } else {
    failed = inst % db !== 0;
  }
  if (failed) yield ERROR;
}

// --- numeric range ---

export function* maximum(v, maximum, instance) {
  if (!isNumeric(instance)) return;
  if (numVal(instance) > numericLimit(maximum)) yield ERROR;
}

export function* minimum(v, minimum, instance) {
  if (!isNumeric(instance)) return;
  if (numVal(instance) < numericLimit(minimum)) yield ERROR;
}

// Draft 3/4: exclusiveMinimum/Maximum are boolean modifiers of minimum/maximum.
export function* maximumLegacy(v, maximum, instance, schema) {
  if (!isNumeric(instance)) return;
  const m = numericLimit(maximum);
  const exclusive = schema.exclusiveMaximum;
  if (exclusive ? numVal(instance) >= m : numVal(instance) > m) yield ERROR;
}

export function* minimumLegacy(v, minimum, instance, schema) {
  if (!isNumeric(instance)) return;
  const m = numericLimit(minimum);
  const exclusive = schema.exclusiveMinimum;
  if (exclusive ? numVal(instance) <= m : numVal(instance) < m) yield ERROR;
}

